<script lang="ts">
  import { untrack } from 'svelte';
  import type { LabFilters, SearchScope, AreaSummary } from '../../design-lab/contract';
  import type { CandidateFacets } from '../../api/TestReleaseRepository';
  import { CATEGORY_PRESENTATIONS } from '../locations/categoryPresentation';
  import { classificationLabel } from '../locations/classificationSummary';
  import { language, tr } from '../../app/language';
  let { filters, sourceId, scope, facets, facetsStatus, areaSummary = null, onapply, onclose }: {
    filters:LabFilters; sourceId:string|null; scope:SearchScope; facets:CandidateFacets|null;
    facetsStatus:'loading'|'ready'|'error'|'unauthorized'; areaSummary?:AreaSummary|null;
    onapply(value:{filters:LabFilters;sourceId:string|null;scope:SearchScope}):void; onclose():void;
  } = $props();
  let draft = $state<LabFilters>(untrack(()=>({...filters,categories:[...filters.categories],countries:[...filters.countries],sources:[...filters.sources],activities:[...filters.activities],precisions:[...filters.precisions]})));
  let draftSource = $state(untrack(()=>sourceId));
  let draftScope = $state(untrack(()=>scope));
  const mapped = ['source_reported','approximate','exact'] as const;
  const names:Record<string,string>={slaughter:'Slaughter',animal_keeping_and_production:'Animal keeping',processing_and_preparation:'Processing',research_and_animal_use:'Research',other_regulated_premises:'Other premises',unclassified:'Unclassified'};
  function toggle(field:'categories'|'countries'|'sources'|'activities',value:string,checked:boolean) { draft={...draft,[field]:checked?[...new Set([...draft[field],value])]:draft[field].filter(item=>item!==value)}; }
  function precision(value:LabFilters['precisions'][number],checked:boolean) { draft={...draft,precisions:checked?[...new Set([...draft.precisions,value])]:draft.precisions.filter(item=>item!==value)}; }
  function toggleMapped(checked:boolean) { draft={...draft,precisions:checked?[...new Set([...draft.precisions,...mapped])]:draft.precisions.filter(item=>!mapped.includes(item as typeof mapped[number]))}; }
  function country(value:string) { try { return new Intl.DisplayNames([$language],{type:'region'}).of(value)??value; } catch { return value; } }
  function clear() { draft={categories:[],countries:[],sources:[],activities:[],precisions:[]};draftSource=null;draftScope=null; }
</script>
<section class="mobile-filter-view" aria-labelledby="mobile-filter-title">
  <header><h2 id="mobile-filter-title">{tr('Filters',$language)}</h2><button type="button" aria-label={tr('Back to results',$language)} onclick={onclose}>×</button></header>
  <div class="mobile-filter-scroll">
    {#if facetsStatus==='loading'}<p role="status">{tr('Loading filters…',$language)}</p>{:else if facetsStatus==='error'||facetsStatus==='unauthorized'}<p role="status">{tr('Filters are unavailable. Search remains available.',$language)}</p>{/if}
    <fieldset><legend>{tr('Activity category',$language)}</legend>{#each Object.entries(CATEGORY_PRESENTATIONS) as [key,presentation]}<label><input type="checkbox" checked={draft.categories.includes(key)} onchange={event=>toggle('categories',key,event.currentTarget.checked)} /><span class="swatch" style:background={presentation.color}></span><span>{tr(names[key]??presentation.label,$language)}</span></label>{/each}</fieldset>
    {#if scope}<fieldset><legend>{tr('Search area',$language)}</legend><label class="whole-row"><input type="checkbox" checked={Boolean(draftScope)} onchange={event=>{draftScope=event.currentTarget.checked?scope:null;}} />{scope.kind==='radius'&&scope.deviceDerived?`${tr('Near me',$language)} · ${tr('{count} miles',$language).replace('{count}',String(Math.round(scope.radiusKm/1.609344)))}`:tr('This map area',$language)}</label></fieldset>{/if}
    <details><summary>{tr('Country',$language)}<span>{draft.countries.length?draft.countries.map(country).join(', '):tr('All countries',$language)}</span></summary><fieldset class="one-column">{#each facets?.countries??[] as facet(facet.value)}<label><input type="checkbox" checked={draft.countries.includes(facet.value)} onchange={event=>toggle('countries',facet.value,event.currentTarget.checked)} />{country(facet.value)} <small>{new Intl.NumberFormat($language).format(facet.count)}</small></label>{/each}</fieldset></details>
    <fieldset><legend>{tr('Location precision',$language)}</legend><label><input type="checkbox" checked={mapped.every(value=>draft.precisions.includes(value))} indeterminate={mapped.some(value=>draft.precisions.includes(value))&&!mapped.every(value=>draft.precisions.includes(value))} onchange={event=>toggleMapped(event.currentTarget.checked)} />{tr('Mapped',$language)}</label>{#each ['unmapped','source_reported','approximate','exact'] as value}<label><input type="checkbox" checked={draft.precisions.includes(value as LabFilters['precisions'][number])} onchange={event=>precision(value as LabFilters['precisions'][number],event.currentTarget.checked)} />{tr(value==='unmapped'?'Unmapped':value==='source_reported'?'Source-reported':value==='approximate'?'Approximate':'Exact',$language)}</label>{/each}</fieldset>
    <details><summary>{tr('Source',$language)}<span>{draft.sources.length?draft.sources.map(value=>facets?.sources.find(facet=>facet.value===value)?.label??value).join(', '):tr('All sources',$language)}</span></summary><fieldset class="one-column">{#if draftSource}<label><input type="checkbox" checked onchange={()=>{draftSource=null;}} />{facets?.sources.find(facet=>facet.value===draftSource)?.label??draftSource}</label>{/if}{#each facets?.sources??[] as facet(facet.value)}<label><input type="checkbox" checked={draft.sources.includes(facet.value)} onchange={event=>toggle('sources',facet.value,event.currentTarget.checked)} />{facet.label??facet.value} <small>{new Intl.NumberFormat($language).format(facet.count)}</small></label>{/each}</fieldset></details>
    {#if facets?.activities.length}<details><summary>{tr('Activity',$language)}<span>{draft.activities.length||''}</span></summary><fieldset class="one-column">{#each facets.activities as facet(facet.value)}<label><input type="checkbox" checked={draft.activities.includes(facet.value)} onchange={event=>toggle('activities',facet.value,event.currentTarget.checked)} />{tr(classificationLabel(facet.label??facet.value),$language)}</label>{/each}</fieldset></details>{/if}
    {#if scope&&areaSummary}<details class="area-facts"><summary>{tr('Activity breakdown',$language)}</summary>{#if areaSummary.status==='ready'}<dl>{#each areaSummary.categories as category}<div><dt>{tr(names[category.key]??category.key,$language)}</dt><dd>{new Intl.NumberFormat($language).format(category.count)}</dd></div>{/each}<div><dt>{tr('Source',$language)}</dt><dd>{areaSummary.sourceCount}</dd></div><div><dt>{tr('Source-reported',$language)}</dt><dd>{areaSummary.sourceReportedCount}</dd></div><div><dt>{tr('Approximate',$language)}</dt><dd>{areaSummary.approximateCount}</dd></div></dl>{:else}<p>{tr(areaSummary.status==='error'?'Area summary unavailable.':'Counting records…',$language)}</p>{/if}</details>{/if}
  </div>
  <footer><button class="clear-mobile-filters" type="button" onclick={clear}>{tr('Clear filters',$language)}</button><button class="apply-mobile-filters" type="button" onclick={()=>onapply({filters:draft,sourceId:draftSource,scope:draftScope})}>{tr('Apply filters',$language)}</button></footer>
</section>
<style>
  .mobile-filter-view{display:flex;flex:1;min-height:0;flex-direction:column;background:var(--panel);color:var(--ink)}
  header{display:flex;align-items:center;justify-content:space-between;min-height:44px;flex:none;padding:0 .85rem .35rem;border-bottom:1px solid var(--line)}h2{font:400 1.3rem/1.2 Georgia,serif;margin:0}button{min-height:44px;border:0;background:none;color:var(--ink);font:inherit;font-size:.75rem;cursor:pointer}header button{width:44px;font-size:1.3rem;color:var(--muted)}
  .mobile-filter-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:0 .85rem .6rem}fieldset{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 .65rem;margin:.55rem 0 .7rem;padding:0;border:0;min-width:0}legend{padding:.3rem 0;font-size:.6875rem;color:var(--muted)}label{display:flex;align-items:center;gap:.45rem;min-height:44px;font-size:.75rem;line-height:1.35;overflow-wrap:anywhere;min-width:0}input{width:16px;height:16px;flex:none;margin:0;accent-color:var(--ink)}.swatch{width:6px;height:6px;border-radius:50%;flex:none}.whole-row{grid-column:1/-1}.one-column{grid-template-columns:minmax(0,1fr);margin:.2rem 0}.one-column small{margin-left:auto;color:var(--muted);font-variant-numeric:tabular-nums}
  details{border-top:1px solid var(--line)}summary{display:flex;align-items:center;justify-content:space-between;gap:.65rem;min-height:44px;font-size:.75rem;cursor:pointer;list-style:none}summary::after{content:'⌄';color:var(--muted);flex:none}summary>span{max-width:65%;min-width:0;margin-left:auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}summary::-webkit-details-marker{display:none}p{font-size:.75rem;line-height:1.5;color:var(--muted)}dl{margin:.3rem 0 .7rem;font-size:.7rem}dl>div{display:flex;justify-content:space-between;gap:1rem;min-height:27px}dd{margin:0;font-variant-numeric:tabular-nums;color:var(--muted)}
  footer{display:flex;align-items:center;justify-content:space-between;gap:.75rem;flex:none;padding:.6rem .85rem max(.6rem,env(safe-area-inset-bottom));border-top:1px solid var(--line)}footer button{padding:.4rem .55rem}.apply-mobile-filters{background:var(--ink);color:var(--panel);padding-inline:1rem}button:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
</style>
